textOptions.schema:
{
  "title": "WatchFile Reference Subject Evaluation Response",
  "description": "Schema for the LLM response when evaluating and optimizing a watchFile reference subject",
  "type": "object",
  "required": [
    "should_update",
    "confidence_score",
    "reasoning",
    "optimized_subject",
    "language",
    "key_improvements",
    "filtering_impact",
    "alignment_notes"
  ],
  "properties": {
    "should_update": {
      "type": "boolean",
      "description": "Whether the reference subject should be updated based on the evaluation"
    },
    "confidence_score": {
      "type": "integer",
      "description": "Confidence score of the modification relevance (0-100). Values ≥30 justify an update."
    },
    "reasoning": {
      "type": "string",
      "description": "Brief explanation of the confidence score and decision rationale (10-150 chars)"
    },
    "optimized_subject": {
      "type": "string",
      "description": "The final optimized reference subject (or original if no update recommended). Max 250 chars."
    },
    "language": {
      "type": "string",
      "description": "ISO 639-1 two-letter language code (uppercase, e.g., EN, FR, ES)"
    },
    "key_improvements": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "List of specific improvements (0-5 items, max 100 chars each)"
    },
    "filtering_impact": {
      "type": "string",
      "description": "Brief explanation of how this optimization improves document relevance filtering (10-100 chars)"
    },
    "alignment_notes": {
      "type": "object",
      "required": [
        "monitoring_type",
        "strategic_questions",
        "actors_sources"
      ],
      "properties": {
        "monitoring_type": {
          "type": ["string", "null"],
          "description": "How the optimized subject aligns with the watchFile's monitoring type (max 200 chars)"
        },
        "strategic_questions": {
          "type": ["string", "null"],
          "description": "How the optimized subject addresses strategic questions (max 200 chars)"
        },
        "actors_sources": {
          "type": ["string", "null"],
          "description": "Relevance to configured actors and sources (max 200 chars)"
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}

