parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "title": "Reference Subject Output Schema v3.0",
  "description": "Dual-purpose reference subject with human-readable and LLM-optimized versions",
  "properties": {
    "referenceSubject": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "human": {
          "type": "object",
          "description": "Human-readable version for WatchFile UI display",
          "additionalProperties": false,
          "properties": {
            "fr": {
              "type": "string",
              "description": "French markdown with all 6 sections (empty sections show placeholder)"
            },
            "en": {
              "type": "string",
              "description": "English markdown with all 6 sections (empty sections show placeholder)"
            }
          },
          "required": ["fr", "en"]
        },
        "llm": {
          "type": "string",
          "description": "LLM-optimized scoring criteria in English markdown with relevance criteria, entity variations, keywords, and decision tree"
        }
      },
      "required": ["human", "llm"]
    }
  },
  "required": ["referenceSubject"],
  "additionalProperties": false
}

